function validateImport(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('The selected file is not a project object.');if(raw.schema&&![core.SCHEMA,'human-project/30'].includes(raw.schema))throw new Error(`Unsupported project schema: ${raw.schema}`);const count=raw.stages?Object.keys(raw.stages).length:raw.stageRecords?Object.keys(raw.stageRecords).length:raw.stageStates?Object.keys(raw.stageStates).length:0;if(count!==30)throw new Error('A project must contain exactly 30 stage records.');const id=raw.job?.JOB_ID||raw.jobId;if(!String(id||'').trim())throw new Error('JOB_ID is required.');return raw;}
function header(){const done=completion();$('#current-project-summary').textContent=`${current.job.JOB_ID} · ${current.job.JOB_TITLE}`;$('#progress-label').textContent=`${done}/30 complete`;$('#progress-bar').style.width=`${done/30*100}%`;$('#project-picker').innerHTML=projects.map((p,i)=>`<option value="${i}"${p===current?' selected':''}>${esc(p.job.JOB_TITLE||p.job.JOB_ID)}</option>`).join('');$('#view-tabs').innerHTML=views.map(v=>`<button data-view="${v}" aria-selected="${current.activeView===v}">${v}</button>`).join('');}
function stageList(stages=core.STAGES){return `<div class="workflow-list">${stages.map(d=>{const s=current.stages[d.number];return `<button class="workflow-button" data-stage="${d.number}"><div class="stage-card${current.activeStage===d.number?' current':''}"><div class="stage-head"><span class="stage-number">${String(d.number).padStart(2,'0')}</span><div><div class="stage-name">${esc(d.title)}</div><div class="stage-meta">${esc(d.result)}</div></div><span class="status ${statusClass(s.status)}">${esc(s.status)}</span></div></div></button>`;}).join('')}</div>`;}
