const jobFields=[['JOB_TITLE','Project title','input'],['JOB_OWNER','Project owner','input'],['EXACT_USER_OBJECTIVE_VERBATIM','Verbatim job request','textarea'],['SUPPLIED_MATERIALS_INVENTORY','Supplied materials / files','textarea'],['REQUIRED_OUTPUT_FORMAT','Output format (optional)','input'],['DEADLINE_OR_TEMPORAL_SCOPE','Temporal scope','input'],['DESIRED_SOURCE_COUNT','Desired / suggested source count','number'],['KNOWN_AUTHORITATIVE_SOURCES','Known authority supplied by user','textarea'],['AVAILABLE_TOOLS','Allowed / required tools','textarea'],['PROHIBITED_ACTIONS','Prohibited actions','textarea'],['EXPLICIT_USER_REQUIREMENTS','Explicit user requirements','textarea']];
function projectView(){const derived=['JOB_ID','DATE_OPENED','CURRENT_ITERATION','CURRENT_STAGE','CURRENT_STATE','CURRENT_INPUT_VERSION','CURRENT_SOURCE_SET_VERSION','CURRENT_REQUIREMENTS_VERSION','CURRENT_TEST_SUITE_VERSION','CURRENT_INSTRUCTION_VERSION','CURRENT_BASELINE_ID','CURRENT_PRODUCT_ID','CURRENT_BLOCKERS','NEXT_REQUIRED_ACTION','LATEST_EVIDENCE_REFERENCE'];return `<div class="panel"><h2 class="section-title">Project information</h2><p class="section-intro">Enter only genuine human-owned User Job Input. The source count is a search target, not a quota and never permission to invent weaker sources. You do not need to know the final file format in advance: Stage 01 determines the actual artifact set and suitable formats. If the chosen agent can reliably construct the requested file or package from a defined representation and sufficient inputs, it should produce that real artifact even when a downstream authoring, build, CAD/CAM, filing, manufacturing, or other consuming system is unavailable. Opening, importing, building, executing, manufacturing, filing, or testing remains separately verified. A specification substitute requires human confirmation and is used only when the requested actual artifact cannot be generated reliably. This static application does not itself access external repositories, websites, or accounts; those capabilities depend on the external agent context you choose to run. The application derives workflow identity, versions, status, counts, and next action.</p><div class="grid-2">${jobFields.map(([k,l,t])=>`<div class="field${t==='textarea'?' full':''}"><label>${l}</label>${t==='textarea'?`<textarea data-job="${k}">${esc(current.job[k]||'')}</textarea>`:`<input data-job="${k}" type="${t==='number'?'number':'text'}"${t==='number'?' min="0" step="1"':''} value="${esc(current.job[k]??'')}">`}</div>`).join('')}</div><div class="button-row"><button class="primary" id="save-job">Save User Job Input</button></div></div><div class="panel"><h2 class="section-title">Application-derived job control</h2>${details('Current derived values',Object.fromEntries(derived.map(k=>[k,current.job[k]])),true)}</div>${Object.keys(current.projectData.userEntered||{}).length?`<div class="panel"><h2 class="section-title">Original project input</h2>${details('User-entered data',current.projectData.userEntered,true)}</div>`:''}`;}
function humanStageMarkup(n,locked){if(n===1){if(current.isRetainedTestProject&&current.stages[1].status==='COMPLETE')return `<div class="notice success">Stage 01 is preserved completed history for this retained project. No historical event has been fabricated or rewritten.</div>`;return `<div class="panel"><h2 class="section-title">Human job intake</h2><p class="section-intro">Stage 01 is an intake conversation. Save any facts you already know here, then send the generated instruction to ChatGPT. The agent should use supplied files and ask only the remaining human-only questions in normal chat. Stay in ChatGPT until it returns the final JSON. HUMAN_INPUT_REQUIRED in this app is only a fallback when a required answer remains unavailable or deferred, or interactive conversation was unavailable.</p><div class="button-row"><button data-view="Project">Open User Job Input</button></div></div>`;}const fields=schema.humanStageFields(n);if(!fields.length)return '';const data=current.stages[n].humanData||{};return `<div class="panel"><h2 class="section-title">Human-owned stage input</h2><div class="grid-2">${fields.map(name=>`<div class="field"><label>${esc(label(name))}</label><input data-human-stage-field="${esc(name)}" value="${esc(data[name]||'')}"${locked?' disabled':''}></div>`).join('')}</div><div class="button-row"><button id="save-human-stage"${locked?' disabled':''}>Save human decision/input</button></div></div>`;}
function humanAnswerControl(q){const id=esc(q.requestId),values=safe(q.allowedValues);switch(q.answerType){case 'TEXT':return `<input data-human-answer="${id}" type="text">`;case 'LONG_TEXT':return `<textarea data-human-answer="${id}"></textarea>`;case 'BOOLEAN':return `<select data-human-answer="${id}"><option value=""></option><option value="true">True</option><option value="false">False</option></select>`;case 'NUMBER':return `<input data-human-answer="${id}" type="number" step="any">`;case 'CHOICE':return `<select data-human-answer="${id}"><option value=""></option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`;case 'MULTI_CHOICE':return `<select data-human-answer="${id}" multiple>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`;case 'DATE':return `<input data-human-answer="${id}" type="date">`;case 'FILE_REFERENCE':{const artifacts=engine.records(current,'artifacts');return `<select data-human-answer="${id}"><option value=""></option>${artifacts.map(a=>`<option value="${esc(engine.recordId(a,'artifacts'))}">${esc(recordValue(a,'FILENAME')||engine.recordId(a,'artifacts'))}</option>`).join('')}</select>`;}default:return `<textarea data-human-answer="${id}"></textarea>`;}}
function clarificationMarkup(n,locked){const items=engine.unresolvedHumanRequests(current,n);if(!items.length)return '';return `<div class="panel"><h2 class="section-title">Human clarification required</h2><p class="section-intro">Answer only these human-authority questions. Answers are type-validated and versioned as User Job Input before a new controlling instruction for the same stage is saved.</p>${items.map(q=>`<div class="field"><label>${esc(q.question)}</label><span class="help">${esc(q.whyRequired)}</span>${humanAnswerControl(q)}</div>`).join('')}<div class="button-row"><button class="primary" id="save-human-answers"${locked?' disabled':''}>Save human answers</button></div></div>`;}
function stageOperations(n){return safe(schema.STAGE_CONTRACTS[n]?.operations).length?schema.STAGE_CONTRACTS[n].operations:['COMPLETE'];}
function selectedOperation(n){const allowed=stageOperations(n);return allowed.includes(operationSelection[n])?operationSelection[n]:allowed[0];}
function currentRunSlots(n){const iteration=String(current.job.CURRENT_ITERATION||'');return engine.records(current,'runs').filter(r=>(Number(r.stage)===n||String(recordValue(r,'ITERATION_ID')||'')===iteration)&&String(recordValue(r,'ITERATION_ID')||'')===iteration);}
function selectedRun(n){const runs=currentRunSlots(n),selected=runs.find(r=>engine.recordId(r,'runs')===runSelection[n]);return selected||runs.find(r=>String(r.completionState||r.status||recordValue(r,'EXECUTION_STATUS')||'').toUpperCase()!=='COMPLETED')||runs[0]||null;}
function promptOptions(n){const operation=selectedOperation(n),options={operation},requiresRun=(schema.operationContract(n,operation)?.scopeRequirements||[]).includes('runId');if(requiresRun){const run=selectedRun(n);if(run){const runId=engine.recordId(run,'runs'),contextId=String(recordValue(run,'CONTEXT_ID')||run.relationships?.CONTEXT_ID||run.scope?.contextId||'');options.scope={runId,contextId};}}return options;}
const operatorScopeKeys=['inputVersion','sourceSetVersion','requirementsVersion','testSuiteVersion','instructionVersion','iterationId','candidateId','runId','contextId','baselineId','productId'];
function currentOperatorScope(n){return globalThis.closedLoopPromptEngine.scopeFor(n,current,promptOptions(n).scope||{});}
function operatorLaneMatches(item,n){if(Number(item?.stage)!==Number(n)||item?.invalidatedBy)return false;const operation=String(item?.envelope?.operation||item?.operation||'COMPLETE'),selected=selectedOperation(n);if(operation!==selected)return false;const actual=item?.envelope?.scope||item?.scope||{},expected=currentOperatorScope(n),required=schema.operationContract(n,operation)?.scopeRequirements||[];for(const key of operatorScopeKeys){const av=actual?.[key],ev=expected?.[key];if(av!==undefined&&av!==null&&av!==''&&ev!==undefined&&ev!==null&&ev!==''&&String(av)!==String(ev))return false;}for(const key of required){if(key==='projectRevision')continue;if(String(actual?.[key]??'')!==String(expected?.[key]??''))return false;}return true;}
function validationLaneRecord(validation){return safe(current.projectData.generatedPrompts).find(x=>(x.instructionId||x.promptId)===validation?.promptId)||validation;}
function acceptedLaneChanges(n){return engine.acceptedChanges(current,n).filter(x=>operatorLaneMatches(x,n));}
