function currentPromptRecord(n){const options=promptOptions(n);return safe(current.projectData.generatedPrompts).filter(x=>promptMatches(x,n,options)&&promptVersionCurrent(x)).at(-1)||null;}
function currentStagePrompt(n){const saved=currentPromptRecord(n);if(saved?.prompt)return saved.prompt;const preview=clone(current);preview.revision=Number(current.revision||0)+1;try{return globalThis.closedLoopPromptEngine.buildPromptRecord(n,preview,promptOptions(n)).prompt;}catch(error){if(error?.code==='MISSING_REQUIRED_PROMPT_SCOPE')return `CONTROLLING INSTRUCTION UNAVAILABLE\n\n${error.message}\n\nReserve/select the exact execution lane shown for this stage, then save or copy the instruction.`;throw error;}}
function operationMarkup(n,locked){const operations=stageOperations(n);if(operations.length<=1)return '';const active=selectedOperation(n);return `<div class="panel"><h2 class="section-title">Stage operation</h2><p class="section-intro">Choose the exact sub-operation before generating or copying its controlling instruction. Each operation has its own readable context, writable collections, and scope.</p><div class="field"><label>Operation</label><select id="operation-picker"${locked?' disabled':''}>${operations.map(op=>`<option value="${esc(op)}"${op===active?' selected':''}>${esc(op.replaceAll('_',' '))}</option>`).join('')}</select></div></div>`;}
function validationMarkup(n){const v=safe(current.projectData.responseValidations).filter(x=>Number(x.stage)===n&&!x.valid&&operatorLaneMatches(validationLaneRecord(x),n)).at(-1);if(!v)return '';return `<div class="notice danger" id="validation-report" tabindex="-1"><strong>Response rejected before canonical mutation.</strong><br><span>Last parsed response: ${esc(v.rawResponseId||'unknown raw response')}. If you pasted or edited a replacement afterward, that replacement has not been evaluated yet; press Parse / validate response again.</span><br>${safe(v.issues).map(x=>esc(`${x.code}: ${x.message}`)).join('<br>')}</div>`;}
function proposalMarkup(n){const p=safe(current.projectData.responseProposals).filter(x=>x.status==='PENDING_OPERATOR_REVIEW'&&operatorLaneMatches(x,n)).at(-1);if(!p)return '';const rows=safe(p.changes).map(c=>({recordType:c.canonicalRecordType||c.canonicalCollection||'stageData',temporaryKey:c.temporaryResponseKey||'',canonicalId:c.canonicalRecordId||'APPLICATION_ASSIGNED',field:c.canonicalField||c.canonicalRelationship||'',proposedValue:c.normalizedValue,jsonPointer:c.jsonPointer||'',evidence:c.evidenceIds||'',validation:'SATISFIED'})),stale=!proposalVersionCurrent(p);return `<div class="panel" id="proposal-heading" tabindex="-1"><h2 class="section-title">Proposed extracted changes</h2>${stale?'<div class="notice warn"><strong>Obsolete instruction version.</strong><br>This proposal cannot be accepted. Save and send the current instruction, then parse the replacement response.</div>':'<p class="section-intro">Nothing below is canonical until you accept the complete validated proposal.</p>'}${details('Proposal diff',rows,true)}<details class="record-card"><summary>Advanced raw proposal<span>Audit</span></summary><div class="record-body">${details('Complete proposal',p)}</div></details><div class="button-row">${stale?'':'<button class="primary" id="accept-proposal">Accept response</button>'}<button id="reject-proposal">Reject response</button><button id="request-correction">Request correction</button></div><div class="field"><label>Correction or refinement needed</label><textarea id="correction-reason" placeholder="State exactly what is missing, incorrect, or should be made more complete."></textarea></div></div>`;}
function stageConfirmationMarkup(n,locked){if(n!==1||current.isRetainedTestProject||current.stages[1].status==='COMPLETE')return '';const accepted=engine.acceptedChanges(current,1).length>0,confirmed=safe(current.projectData.stageConfirmations).some(x=>Number(x.stage)===1&&x.confirmed&&!x.invalidatedBy);if(!accepted||confirmed)return '';return `<div class="panel"><h2 class="section-title">Human intent confirmation</h2><p class="section-intro">Confirm only that the accepted Stage 01 representation matches the objective and deliverable you intend.</p><div class="button-row"><button class="primary" id="confirm-stage-one"${locked?' disabled':''}>Confirm represented intent</button></div></div>`;}
function acceptedStageMarkup(n){const s=current.stages[n],collections=schema.STAGE_CONTRACTS[n].allowedCollections,records=collections.flatMap(c=>engine.records(current,c,{stage:n}).map(r=>({collection:c,...r})));return `<div class="panel"><h2 class="section-title">Accepted canonical stage record</h2><p class="section-intro">Agent-owned and application-derived data are read-only after validated ingestion. Corrections use the owning authority's controlled path; canonical application state is not directly editable.</p>${Object.keys(s.agentData||{}).length?details('Accepted agent data',s.agentData):'<div class="empty-state">No accepted agent data yet.</div>'}${Object.keys(s.derivedData||{}).length?details('Application-derived values',s.derivedData):''}${records.length?details('Accepted linked records',records):''}${s.gate?.reasons?.length?`<div class="notice warn"><strong>Completion gate is not satisfied.</strong><br>${s.gate.reasons.map(esc).join('<br>')}</div>`:`<div class="notice success">Completion gate is satisfied by current canonical evidence.</div>`}${acceptedLaneChanges(n).length&&!current.isRetainedTestProject?`<details class="record-card"><summary>Refine accepted result<span>Controlled</span></summary><div class="record-body"><div class="field"><label>Why refinement is required</label><textarea id="accepted-refinement-reason"></textarea></div><button id="refine-accepted-response">Invalidate accepted result and request refinement</button></div></details>`:''}</div>`;}
function controls(d,locked){const n=d.number,allowFresh=schema.STAGE_CONTRACTS[n].supportCollections.includes('freshContexts'),runBatch=n===11||([17,19].includes(n)&&selectedOperation(n)==='EXECUTE_RUN'),humanBlockers=engine.openBlockers(current,n).filter(x=>x.source==='HUMAN_DECISION');return `<details class="record-card"><summary>Supporting records<span>Contextual</span></summary><div class="record-body"><p class="section-intro">Use authority-specific controls only. Canonical IDs, lifecycle state, timestamps, and hashes are application-assigned.</p><div class="field"><label>Blocker reason</label><textarea id="blocker-reason"></textarea></div><div class="button-row"><button id="add-blocker"${locked?' disabled':''}>Create blocker</button></div>${humanBlockers.length?`<div class="field"><label>Resolution evidence for human-created blocker</label><textarea id="blocker-resolution-evidence"></textarea></div>${humanBlockers.map(b=>`<div class="button-row"><button data-resolve-blocker="${esc(engine.recordId(b,'blockers'))}">Resolve ${esc(engine.recordId(b,'blockers'))}</button></div>`).join('')}`:''}${allowFresh?`<div class="field"><label>External fresh-context identifier</label><input id="fresh-context-id"><span class="help">Fills the next reserved context slot for the current iteration when one exists.</span></div><div class="button-row"><button id="add-fresh-context"${locked?' disabled':''}>Register fresh context</button></div>`:''}${runBatch?`<div class="button-row"><button id="reserve-run-batch"${locked?' disabled':''}>Reserve ten run/context slots</button></div>`:''}<div class="field"><label>Operator label</label><input id="operator-label" value="HUMAN_OPERATOR"><span class="help">Identity assurance: SELF_ASSERTED</span></div></div></details>`;}
function selectedArtifactIds(stage=current.activeStage){return safe(current.stages[stage]?.authorizedFiles).map(x=>String(x.artifactId||x.id||'')).filter(Boolean);}
function currentStageProduct(){const productId=String(current.job.CURRENT_PRODUCT_ID||'').trim();if(!productId||['NONE','NOT APPLICABLE','UNKNOWN','PENDING','UNASSIGNED'].includes(productId.toUpperCase()))return null;return engine.records(current,'products').find(record=>engine.recordId(record,'products')===productId&&Number(record.stage)===21&&engine.isActiveRecord(record))||null;}
function artifactControlMarkup(n,locked){if(n===19)return `<div class="panel"><h2 class="section-title">Unchanged candidate control</h2><p class="section-intro">Stage 19 reuses the exact current Stage 17 frozen candidate identity and hashes. Do not select replacement files or create a new candidate.</p><div class="button-row"><button id="begin-unchanged-confirmation"${locked?' disabled':''}>Begin unchanged confirmation using Stage 17 candidate</button></div></div>`;const applicable=[10,17,20,21,25].includes(n),files=safe(current.stages[n].authorizedFiles),productReady=n!==21||Boolean(currentStageProduct()),fileLocked=locked||!productReady;return `<div class="panel"><h2 class="section-title">${applicable?'Artifact control':'Authorized files for this stage'}</h2><p class="section-intro">Actual selected bytes are stored in IndexedDB, hashed by the application, read back, and rehashed before becoming canonical artifact identities. If an agent response declares attachments, attach the exact returned files here before Parse / validate; a filename, hash claim, or code block is not file possession.</p>${n===21&&!productReady?'<div class="notice warn">Reserve the Stage 21 product execution before selecting finished-product files. The reserved PRODUCT_ID controls artifact scope, inventory, and lineage.</div>':''}<div class="grid-2"><div class="field"><label>Select exact files</label><input id="stage-files" type="file" multiple${fileLocked?' disabled':''}></div><div class="field"><label>Select structured package folder</label><input id="stage-directory" type="file" webkitdirectory directory multiple${fileLocked?' disabled':''}><span class="help">Use folder selection when directory structure is meaningful; canonical filenames preserve paths relative to the selected root.</span></div></div>${files.length?details('Verified artifact bytes',files,true):'<div class="empty-state">No verified stage artifact bytes.</div>'}<div class="button-row">${[10,17].includes(n)?`<button id="freeze-candidate"${locked?' disabled':''}>${n===17?'Freeze corrected candidate':'Freeze selected candidate'}</button>`:''}${n===20?`<button id="freeze-baseline"${locked?' disabled':''}>Freeze selected baseline</button>`:''}${n===21?`<button id="reserve-product-execution"${locked?' disabled':''}>Reserve product execution</button>`:''}</div></div>`;}
function runBatchMarkup(n){if(![11,12,17,19].includes(n))return '';const runs=currentRunSlots(n),selected=selectedRun(n),rows=runs.map(r=>({RUN_ID:engine.recordId(r,'runs'),CONTEXT_ID:recordValue(r,'CONTEXT_ID'),ITERATION_ID:recordValue(r,'ITERATION_ID'),CANDIDATE_ID:recordValue(r,'CANDIDATE_ID'),operation:r.operation||'EXECUTE_RUN',promptIdentity:r.promptInstructionId||r.currentPromptId||'NOT YET GENERATED',rawResponseStatus:r.rawResponseStatus||'NOT RECEIVED',validationStatus:r.validationStatus||'NOT VALIDATED',proposalStatus:r.proposalStatus||'NONE',acceptedStatus:r.completionState||r.status||recordValue(r,'EXECUTION_STATUS')||'RESERVED',receipt:r.receiptId||'NONE'}));const picker=(schema.operationContract(n,selectedOperation(n))?.scopeRequirements||[]).includes('runId')&&runs.length?`<div class="field"><label>Run slot for this instruction</label><select id="run-slot-picker">${runs.map(r=>{const id=engine.recordId(r,'runs');return `<option value="${esc(id)}"${selected&&engine.recordId(selected,'runs')===id?' selected':''}>${esc(id)} · ${esc(recordValue(r,'CONTEXT_ID')||'NO CONTEXT')}</option>`;}).join('')}</select></div>`:'';return `<div class="panel"><h2 class="section-title">Run batch</h2>${picker}${rows.length?details('Application-reserved run/context slots',rows,true):'<div class="empty-state">No run batch has been reserved.</div>'}</div>`;}
function testExecutionGuidanceMarkup(n){
  const plan=engine.testExecutionPlan(current),verificationStage=n===6||[7,8,9,10,11,12,17,19,22,23,24,25].includes(n);
  if(!verificationStage||(!plan.total&&n!==6))return '';
  const labels={APPLICATION_DETERMINISTIC:'Application',EXTERNAL_AGENT_TOOL:'Agent/tool',INDEPENDENT_AGENT_REVIEW:'Independent review',HUMAN_INSPECTION:'Human inspection',EXTERNAL_SYSTEM:'External system',UNAVAILABLE:'Unavailable'};
  const summary=Object.entries(plan.counts).filter(([,count])=>count).map(([mode,count])=>`<span>${esc(labels[mode]||mode)}: <strong>${count}</strong></span>`).join('');
  const actionRows=Object.entries(plan.counts).filter(([,count])=>count).map(([mode,count])=>({mode:labels[mode]||mode,tests:count,nextAction:plan.items.find(item=>item.executionMode===mode)?.operatorAction||''}));
  if(plan.unsupportedApplicationTestIds.length)actionRows.unshift({mode:'Invalid application executor claim',tests:plan.unsupportedApplicationTestIds.length,nextAction:'Request a corrected Stage 6 test definition. No registered application-native executor exists for the declared capability; do not run or accept a substitute execution.'});
  const intro=n===6?'Stage 6 defines how each requirement will be verified. A test definition is not automatically executable code and does not mean a test has run.':'Execution responsibility comes from the accepted test definitions; use only the executor and capability actually declared for each test.';
  return `<div class="panel"><h2 class="section-title">Verification execution</h2><p class="section-intro">${esc(intro)}</p>${summary?`<div class="stage-action-strip">${summary}</div>`:''}${plan.unavailableTestIds.length?`<div class="notice warn">${plan.unavailableTestIds.length} test${plan.unavailableTestIds.length===1?' is':'s are'} blocked by unavailable capability. Do not claim execution until a valid capability or equivalent verification path exists.</div>`:''}${plan.missingArtifactTestIds.length?`<div class="notice warn">${plan.missingArtifactTestIds.length} test${plan.missingArtifactTestIds.length===1?' requires':'s require'} exact artifact bytes that are missing or unverified. Restore or attach the exact files before execution; browser storage alone does not give an external executor access.</div>`:''}${actionRows.length?details('Who performs the current tests',actionRows):'<div class="notice">For each test, the agent must declare the execution mode, required capability, artifact requirements, procedure, expected result, failure condition, and evidence.</div>'}</div>`;
}
function provenanceMarkup(n){const manifests=safe(current.projectData.extractionManifests).filter(m=>Number(m.stage)===n),rows=manifests.flatMap(m=>safe(m.entries||m.changes).map(e=>({canonicalField:`${e.canonicalCollection||e.canonicalRecordType||''}/${e.canonicalRecordId||''}/${e.canonicalField||''}`,manifestId:m.manifestId,responsePointer:e.jsonPointer||e.JSON_POINTER_IN_RESPONSE||'',rawResponseId:m.rawResponseId||m.RAW_RESPONSE_ID,promptId:m.promptId||m.PROMPT_ID,evidenceIds:e.evidenceIds||[]})));return rows.length?`<div class="panel"><h2 class="section-title">Provenance navigation</h2><p class="section-intro">Canonical field → extraction manifest → response JSON pointer → raw response → controlling prompt → evidence.</p>${details('Traceable accepted values',rows)}</div>`:'';}
function workflow(){const n=current.activeStage,d=core.STAGES[n-1],s=current.stages[n],lock=stageLocked(n),locked=Boolean(lock)&&s.status!=='COMPLETE',savedPrompt=currentPromptRecord(n),prompt=savedPrompt?.prompt||currentStagePrompt(n),responseLocked=locked||s.status==='COMPLETE',promptIntro=savedPrompt?'This exact saved instruction is the controlling request. Its identity and strict response contract are embedded below.':'This is an unsaved preview. Save or copy it before sending it to an agent; only the committed instruction identity is controlling.';return `<div class="panel"><div class="stage-nav"><button data-stage="${Math.max(1,n-1)}" aria-label="Previous stage">‹</button><select id="stage-picker">${core.STAGES.map(x=>`<option value="${x.number}"${x.number===n?' selected':''}>${String(x.number).padStart(2,'0')} — ${esc(x.title)}</option>`).join('')}</select><button data-stage="${Math.min(30,n+1)}" aria-label="Next stage">›</button></div></div><div class="hero stage-hero"><div class="hero-top"><div><h2>Stage ${String(n).padStart(2,'0')} — ${esc(d.title)}</h2><p>${esc(d.result)}</p></div><span class="status ${statusClass(s.status)}">${esc(s.status)}</span></div><div class="stage-action-strip"><span>${esc(current.job.CURRENT_STATE)}</span><span>${esc(current.job.NEXT_REQUIRED_ACTION)}</span></div></div>${locked?`<div class="notice warn">${esc(lock)}</div>`:''}${n===1?'<div class="notice"><strong>Talk with the agent before final JSON.</strong> Answer needed questions in ChatGPT and stay there until the agent has enough information and returns the final JSON. Return to this app for that final JSON; use the app clarification controls only when an unresolved fallback question is explicitly shown here.</div>':''}${n===2?'<div class="notice"><strong>Independent external sources only.</strong> Prefer primary/official controlling authority where it exists; otherwise use the most authoritative, reputable, direct evidence appropriate to the domain. Existing target and repository artifacts may be implementation evidence for an audit/repair job, but they cannot become independent source authority merely by existing.</div>':''}${humanStageMarkup(n,locked)}${clarificationMarkup(n,locked)}${operationMarkup(n,locked)}${runBatchMarkup(n)}${testExecutionGuidanceMarkup(n)}<div class="panel"><h2 class="section-title">Agent loop</h2><div class="operator-loop" aria-label="Normal stage workflow"><div class="operator-step"><b>1</b><span>Send instruction</span></div><div class="operator-step"><b>2</b><span>Answer agent questions</span></div><div class="operator-step"><b>3</b><span>Paste final JSON</span></div><div class="operator-step"><b>4</b><span>Validate and review</span></div></div><details class="record-card"><summary>How this stage works<span>?</span></summary><div class="record-body"><p class="section-intro">Use ChatGPT as the conversation. The agent should ask plain-language human-only questions there and explain briefly why they matter. Stay in that chat until the agent says it has enough information and returns one final JSON object. Paste only that final JSON here. If research or requirements later reveal a new human-only fact or decision, the agent should ask you then rather than guess. If the app rejects a response, the rejected response remains audit history; edit or replace the response and press Parse / validate again. You should not repair JSON structure or invent missing agent data yourself.</p></div></details></div><div class="panel"><h2 class="section-title">Generated instruction</h2><p class="section-intro">${promptIntro}</p><pre class="prompt expandable-prompt" id="generated-prompt" tabindex="0">${esc(prompt)}</pre><div class="prompt-toolbar"><span class="prompt-meta">${prompt.length.toLocaleString()} characters · exact controlling copy block</span><div class="button-row"><button id="toggle-prompt" aria-expanded="false">Expand preview</button><button id="save-prompt"${locked?' disabled':''}>Save instruction</button><button class="primary" id="copy-prompt"${locked?' disabled':''}>Save and copy instruction</button></div></div></div>${pendingProposal()?'':validationMarkup(n)}<div class="panel"><h2 class="section-title">Returned agent response</h2><p class="section-intro">Paste only the final strict JSON from ChatGPT after the conversation is complete. If ChatGPT is still asking you questions, answer them there instead of pasting that conversation here. Parse / validate preserves the raw response first, then validates it without changing canonical project records. If the final response declares returned files, attach those exact files in Authorized files for this stage before parsing.</p><textarea class="code-text stage-output" id="stage-output"${responseLocked?' disabled':''}>${esc(s.responseDraft||'')}</textarea><div class="stage-output-hint"><span>Complete JSON only — no Markdown wrapper.</span><span>${s.responseDraft?`${s.responseDraft.length.toLocaleString()} characters pasted`:'No response pasted yet'}</span></div><div class="button-row"><button class="primary" id="parse-output"${responseLocked?' disabled':''}>Parse / validate response</button></div></div>${proposalMarkup(n)}${stageConfirmationMarkup(n,locked)}${acceptedStageMarkup(n)}${artifactControlMarkup(n,locked)}${provenanceMarkup(n)}${controls(d,locked)}`;}
function records(){const d=current.projectData,groups=[['Original user-entered data',d.userEntered],['Stage records',d.stageRecords],['Generated instructions',d.generatedPrompts],['Raw agent responses',d.rawResponses],['Parsed proposals',d.responseProposals],['Validation reports',d.responseValidations],['Accepted canonical changes',d.acceptedChanges],['Rejected responses',d.rejectedResponses],['Extraction manifests',d.extractionManifests],['Human input requests',d.humanInputRequests],['Human input answers',d.humanInputAnswers],['Stage confirmations',d.stageConfirmations],['Generated outputs',d.generatedOutputs],['Output receipts',d.outputReceipts],['External sources',d.sources],['Source conflicts',d.sourceConflicts],['Research',d.research],['Candidate requirements',d.candidateRequirements],['Requirements',d.requirements],['Tests',d.tests],['Failure tests',d.failureTests],['Production instructions',d.instructions],['Instruction reviews',d.preflightRecords],['Fresh contexts',d.freshContexts],['Candidate freezes',d.candidateFreezes],['Iterations',d.iterations],['Run records',d.runs],['Verification records',d.verification],['Cross-run comparisons',d.comparisons],['Defects',d.defects],['Root causes',d.rootCauses],['Regressions',d.regressions],['Changes and invalidations',d.changes],['Blockers',d.blockers],['Convergence',d.convergenceRecords],['Confirmation',d.confirmationRecords],['Baselines',d.baselines],['Products',d.products],['Deterministic verification',d.deterministicResults],['Independent meaning review',d.meaningResults],['Adversarial review',d.adversarialResults],['Representation inspections',d.representationInspections],['Process audits',d.processAudits],['Product audits',d.productAudits],['Release gate reviews',d.releaseGateReviews],['Release records',d.releaseRecords],['Artifact identity records',d.artifactIdentities],['Evidence investigations',d.evidenceInvestigations],['Evidence chains',d.evidenceChains],['Permanent registry',d.permanentRegistry],['New-job reset records',d.newJobResets],['History',d.history],['Migration archives',d.migrationArchives],['Recovered original projects',d.recoveredProjects]];return `<div class="panel"><h2 class="section-title">Complete project record</h2><p class="section-intro">All actual User Job Input, prompts, raw responses, accepted canonical records, evidence, decisions, release records, and retained failures remain inspectable.</p><div class="record-stack">${groups.filter(([,v])=>v&&(!(Array.isArray(v))||v.length)&&(!(typeof v==='object'&&!Array.isArray(v))||Object.keys(v).length)).map(([n,v])=>details(n,v)).join('')}</div></div>`;}
function files(){const all=[...safe(current.projectData.artifacts),...Object.values(current.stages).flatMap(s=>safe(s.authorizedFiles))];return `<div class="panel"><h2 class="section-title">Files and artifacts</h2><p class="section-intro">Hashes are calculated only from actual bytes available to the browser. Metadata-only or external references remain identified as such.</p>${all.length?details('Recorded file identities',all,true):'<div class="empty-state">No file bytes or artifact metadata have been recorded.</div>'}</div>`;}
function release(){const metrics=engine.releaseMetrics(current);return `<div class="hero release-hero"><div class="hero-top"><div><h2>Release control</h2><p>Release requires Stage 27 acceptance and exact audited-versus-delivery byte identity.</p></div><span class="status ${statusClass(metrics.determination)}">${esc(metrics.determination)}</span></div></div><div class="panel"><h2 class="section-title">Release gate</h2>${details('Calculated release metrics',metrics,true)}<div class="button-row"><button id="calculate-release-state">Recalculate release determination</button></div></div><div class="panel"><h2 class="section-title">Exact artifact identity</h2><p class="section-intro">Select the audited canonical files and the exact delivery files. The application hashes both selections. Audited selections must match one existing canonical artifact exactly; delivery selections are then compared to that canonical identity by authorized filename, byte size, and SHA-256.</p><div class="grid-2"><div class="field"><label>Audited canonical files</label><input id="audited-files" type="file" multiple><label>or audited package folder</label><input id="audited-directory" type="file" webkitdirectory directory multiple></div><div class="field"><label>Exact delivery files</label><input id="release-files" type="file" multiple><label>or delivery package folder</label><input id="release-directory" type="file" webkitdirectory directory multiple></div></div><div class="button-row"><button id="hash-audited">Verify audited selection</button><button id="hash-release">Hash delivery selection</button><button class="primary" id="compare-release">Compare exact identity</button></div>${details('Release state',current.release,true)}</div>`;}
function render(){if(!current)return;header();$('#screen').innerHTML=({Overview:overview,Project:projectView,Workflow:workflow,Records:records,Files:files,Release:release}[current.activeView]||overview)();wire();}
async function saveJob(){const next=clone(current),changed=[];document.querySelectorAll('[data-job]').forEach(x=>{const key=x.dataset.job,value=x.type==='number'?(x.value===''?null:Number(x.value)):x.value;if(next.job[key]!==value){next.job[key]=value;changed.push(key);}});if(!changed.length)return render();next.projectData.userEntered={...next.projectData.userEntered,objective:next.job.EXACT_USER_OBJECTIVE_VERBATIM,suppliedMaterials:next.job.SUPPLIED_MATERIALS_INVENTORY,requiredOutputFormat:next.job.REQUIRED_OUTPUT_FORMAT,deadlineOrTemporalScope:next.job.DEADLINE_OR_TEMPORAL_SCOPE,desiredSourceCount:next.job.DESIRED_SOURCE_COUNT,knownAuthorities:next.job.KNOWN_AUTHORITATIVE_SOURCES,availableTools:next.job.AVAILABLE_TOOLS,prohibitedActions:next.job.PROHIBITED_ACTIONS,explicitRequirements:String(next.job.EXPLICIT_USER_REQUIREMENTS||'').split(/\r?\n/).filter(Boolean)};engine.recordHumanInputVersion(next,changed,'HUMAN_OPERATOR');if(next.stages[1].status==='COMPLETE'&&!next.isRetainedTestProject)engine.invalidateStageForAuthorityChange(next,{stage:1,reason:'User Job Input changed after Stage 01 completion.',operatorLabel:'HUMAN_OPERATOR'});await persistReplacement(next);render();}
async function saveHumanStageFields(){const next=clone(current),stage=next.activeStage,changed=[];for(const x of document.querySelectorAll('[data-human-stage-field]')){const field=x.dataset.humanStageField,value=x.value;if(next.stages[stage].humanData[field]!==value){engine.recordHumanDecision(next,{stage,field,value,operatorLabel:$('#operator-label')?.value.trim()||'HUMAN_OPERATOR'});changed.push(field);}}if(changed.length){engine.recordHumanInputVersion(next,changed.map(x=>`STAGE_${stage}:${x}`),'HUMAN_OPERATOR');if(current.stages[stage].status==='COMPLETE')engine.invalidateStageForAuthorityChange(next,{stage,reason:'Human-owned stage input changed after completion.',operatorLabel:$('#operator-label')?.value.trim()||'HUMAN_OPERATOR'});await persistReplacement(next);}render();}
async function saveHumanAnswers(){const requests=new Map(safe(current.projectData.humanInputRequests).map(q=>[q.requestId,q]));const answers=Object.fromEntries([...document.querySelectorAll('[data-human-answer]')].map(x=>{const q=requests.get(x.dataset.humanAnswer);let value;if(x.multiple)value=[...x.selectedOptions].map(o=>o.value);else if(q?.answerType==='BOOLEAN')value=x.value===''?'':x.value==='true';else if(x.type==='number')value=x.value===''?'':Number(x.value);else value=x.value;return [x.dataset.humanAnswer,value];}));try{const result=ingestion.answerHumanInput(current,answers,{operator:$('#operator-label')?.value.trim()||'HUMAN_OPERATOR'});await persistReplacement(result.project);announce('human answers saved');render();}catch(error){const target=error?.requestId?document.querySelector(`[data-human-answer="${CSS.escape(error.requestId)}"]`):null;target?.focus();alert(error.message||error);}}
